mapper.select:
select c.chunk_id AS "chunkId", c.document_id AS "documentId", d.title AS "title", d.category AS "category", d.source_type AS "sourceType", d.source_id AS "sourceId", c.chunk_text AS "chunkText", 1 - (c.embedding <=> CAST(#{queryVector} AS vector)) AS "score" from crm_kb_chunk c join crm_kb_document d on d.document_id = c.document_id where d.status = 'published' and d.del_flag = '0' and d.index_status = 'indexed'
and d.category in
#{cat}
and 1 - (c.embedding <=> CAST(#{queryVector} AS vector)) >= #{minScore} order by c.embedding <=> CAST(#{queryVector} AS vector) limit #{topK}
